    M = int(data[1])
    S = data[2]

    L = 1 << N
    trans = [[0] * 26 for _ in range(L)]

    for mask in range(L):
        old = [0] * (N + 1)
        for j in range(1, N + 1):
            old[j] = old[j - 1] + ((mask >> (j - 1)) & 1)

        for c in range(26):
            new = [0] * (N + 1)
            for j in range(1, N + 1):
