import sys
from bisect import bisect_left

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    X = next(it)

    groups = [[], [], [], []]
    totals = [0] * 4

    for _ in range(N):
        v = next(it)
        a = next(it)
        c = next(it)
        groups[v].append((a, c))
        totals[v] += a

    dp = [None] * 4

    for v in range(1, 4):
        arr = [0] * (X + 1)
        for a, c in groups[v]:
            for cost in range(X, c - 1, -1):
                val = arr[cost - c] + a
                if val > arr[cost]:
                    arr[cost] = val
        dp[v] = arr

    low = 0
    high = min(totals[1], totals[2], totals[3]) + 1

    while high - low > 1:
        mid = (low + high) // 2
        total_cost = 0

        for v in range(1, 4):
            total_cost += bisect_left(dp[v], mid)
            if total_cost > X:
                break

        if total_cost <= X:
            low = mid
        else:
            high = mid

    print(low)


if __name__ == "__main__":
    main()

