import sys

MOD = 998244353

def calc_total(exps, h, pow_p):
    if h < 0:
        return 0
    for a in exps:
        if a > h:
            return 0
    dp = pow_p[:h + 1]
    for a in exps:
        new = [0] * (h + 1)
        if a == 0:
            for y in range(h + 1):
                new[y] = dp[y] * pow_p[y] % MOD
        else:
            for y in range(h + 1):
                val = 0
                if y >= a:
                    val += dp[y - a]
                if y + a <= h:
                    val += dp[y + a]
                if val >= MOD:
                    val -= MOD
                new[y] = val * pow_p[y] % MOD
        dp = new
    return sum(dp) % MOD

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return
    N = data[0]
    A = data[1:1 + N - 1]

    exps = {}
    for i, a in enumerate(A):
        x = a
        d = 2
        while d * d <= x:
            if x % d == 0:
                cnt = 0
                while x % d == 0:
                    x //= d
                    cnt += 1
                if d not in exps:
                    exps[d] = [0] * (N - 1)
                exps[d][i] = cnt
            d += 1
        if x > 1:
            if x not in exps:
                exps[x] = [0] * (N - 1)
            exps[x][i] = 1

    ans = 1
    for p, arr in exps.items():
        H = sum(arr)
        pow_p = [1] * (H + 1)
        for e in range(1, H + 1):
            pow_p[e] = pow_p[e - 1] * p % MOD

        totalH = calc_total(arr, H, pow_p)
        if H > 0:
            totalHminus = calc_total(arr, H - 1, pow_p)
        else:
            totalHminus = 0

        F = (totalH - pow(p, N, MOD) * totalHminus) % MOD
        ans = ans * F % MOD

    print(ans)

if __name__ == "__main__":
