import sys


def mat_mul(A, B, mod):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ci = C[i]
        Ai = A[i]
        for k in range(n):
            aik = Ai[k]
            if aik:
                Bk = B[k]
                for j in range(n):
                    Ci[j] += aik * Bk[j]
        for j in range(n):
            Ci[j] %= mod
    return C


def mat_pow(F, exp, mod):
    n = len(F)
    res = [[0] * n for _ in range(n)]
    for i in range(n):
        res[i][i] = 1 % mod

    base = [row[:] for row in F]
    while exp > 0:
        if exp & 1:
            res = mat_mul(res, base, mod)
        base = mat_mul(base, base, mod)
        exp >>= 1
    return res


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    p = data[1]

    A = []
    idx = 2
    for _ in range(N):
        A.append(data[idx:idx + N])
        idx += N

    if p == 2:
        val = N % 2
        line = " ".join([str(val)] * N)
        sys.stdout.write("\n".join([line] * N))
        return

    K = 0
    F = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            if A[i][j] == 0:
                K += 1
            else:
                F[i][j] = A[i][j] % p

    Fp = mat_pow(F, p, p)
    T = [[0] * N for _ in range(N)]

    # Contributions from zero self-loops (a, a)
    for a in range(N):
        if A[a][a] == 0:
            # e^(p-1) followed by a fixed edge (a, d)
            for d in range(N):
                if d != a and A[a][d] != 0:
                    T[a][d] = (T[a][d] + A[a][d]) % p

            # a fixed edge (c, a) followed by e^(p-1)
            for c in range(N):
                if c != a and A[c][a] != 0:
                    T[c][a] = (T[c][a] + A[c][a]) % p

    # For p = 3, a non-self-loop zero edge can appear twice:
    # (a, b) -> (b, a) -> (a, b)
    if p == 3:
        for a in range(N):
            for b in range(N):
                if a != b and A[a][b] == 0:
                    if A[b][a] != 0:
                        T[a][b] = (T[a][b] + A[b][a]) % p

    sign = 1 if K % 2 == 0 else p - 1

    ans = [[0] * N for _ in range(N)]
    for i in range(N):
        for j in range(N):
            ans[i][j] = ((Fp[i][j] + T[i][j]) % p) * sign % p

    out_lines = []
    for i in range(N):
        out_lines.append(" ".join(str(ans[i][j]) for j in range(N)))
    sys.stdout.write("\n".join(out_lines))


if __name__ == "__main__":
    main()
