import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    adj = [[] for _ in range(N)]

    idx = 2
    for _ in range(M):
        x = data[idx] - 1
        y = data[idx + 1] - 1
        z = data[idx + 2]
        idx += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    d = [-1] * N
    ans = [0] * N

    for start in range(N):
        if d[start] != -1:
            continue

        comp = []
        stack = [start]
        d[start] = 0

        while stack:
            u = stack.pop()
            comp.append(u)

            for v, z in adj[u]:
                nd = d[u] ^ z
                if d[v] == -1:
                    d[v] = nd
                    stack.append(v)
                else:
                    if d[v] != nd:
                        sys.stdout.write("-1\n")
                        return

        size = len(comp)
        t = 0

        for b in range(31):
            mask = 1 << b
            cnt = 0
            for v in comp:
                if d[v] & mask:
                    cnt += 1

            if cnt * 2 > size:
                t |= mask

        for v in comp:
            ans[v] = t ^ d[v]

    sys.stdout.write(" ".join(map(str, ans)) + "\n")


