import sys

MOD = 998244353

def main():
    input = sys.stdin.readline
    N = int(input().strip())
    s = input().strip()

    # Precompute multiplication table for 2x2 Boolean matrices encoded as 4-bit ints.
    # bit0: (0,0), bit1: (0,1), bit2: (1,0), bit3: (1,1)
    mul = [[0] * 16 for _ in range(16)]
    for A in range(16):
        a00 = A & 1
        a01 = (A >> 1) & 1
        a10 = (A >> 2) & 1
        a11 = (A >> 3) & 1
        for B in range(16):
            b00 = B & 1
            b01 = (B >> 1) & 1
            b10 = (B >> 2) & 1
            b11 = (B >> 3) & 1
            c00 = (a00 & b00) | (a01 & b10)
            c01 = (a00 & b01) | (a01 & b11)
            c10 = (a10 & b00) | (a11 & b10)
            c11 = (a10 & b01) | (a11 & b11)
            code = c00 | (c01 << 1) | (c10 << 2) | (c11 << 3)
            mul[A][B] = code

    # Allowed t values for s_i = 0 and s_i = 1.
    allowed_t = {
        0: [-1, 0, 1],
        1: [-1, 0, 1, 2]
    }

    R_codes = {0: [], 1: []}
    for s_val in (0, 1):
        for t in allowed_t[s_val]:
            code = 0
            for prev in (0, 1):
                for curr in (0, 1):
                    diff = prev - curr
                    if s_val == 0:
                        ok = (t == diff)
                    else:
                        ok = (t == diff or t == diff + 1)
                    if ok:
                        bit = prev * 2 + curr
                        code |= (1 << bit)
            R_codes[s_val].append(code)

    # Find all reachable relation matrices from the identity matrix (code 9).
    generators = set(R_codes[0] + R_codes[1])
    start = 9  # identity matrix
    reachable = {start}
    queue = [start]
    while queue:
        M = queue.pop()
        for R in generators:
            nxt = mul[M][R]
            if nxt not in reachable:
                reachable.add(nxt)
                queue.append(nxt)

    reachable_list = sorted(reachable)
    idx_map = {code: i for i, code in enumerate(reachable_list)}
    S = len(reachable_list)

    # Precompute flat transition lists for each s value.
    trans_flat = {0: [], 1: []}
    for s_val in (0, 1):
        for i, M in enumerate(reachable_list):
            counts = {}
            for R in R_codes[s_val]:
                nxt = mul[M][R]
                counts[nxt] = counts.get(nxt, 0) + 1
            for nxt, cnt in counts.items():
                trans_flat[s_val].append((i, idx_map[nxt], cnt))

    dp = [0] * S
    dp[idx_map[start]] = 1

    for ch in s:
        typ = 0 if ch == '0' else 1
        new = [0] * S
        for i, nxt, mult in trans_flat[typ]:
            new[nxt] += dp[i] * mult
        for i in range(S):
            new[i] %= MOD
        dp = new

    ans = 0
    for i, M in enumerate(reachable_list):
        if (M & 1) or (M & 8):  # trace nonzero: bit0 or bit3
            ans += dp[i]
    ans %= MOD
    print(ans)

if __name__ == "__main__":
    main()
