    N = data[0]
    A = data[1:1 + N]

    INF_NEG = -10**30
    dp_odd = INF_NEG   # max sum of valid subsequence ending at an odd position
    dp_even = INF_NEG  # max sum of valid subsequence ending at an even position

    for i, a in enumerate(A, start=1):
        if i % 2 == 1:
            best = a  # start a new subsequence at this odd position
            if dp_even != INF_NEG:
                best = max(best, dp_even + a)
            dp_odd = max(dp_odd, best)
        else:
            if dp_odd != INF_NEG:
                dp_even = max(dp_even, dp_odd + a)

    if N % 2 == 1:
        ans = dp_odd
    else:
        ans = max(0, dp_even)

    print(ans)

