import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    M = int(data[1])
    S = data[2]
    T = data[3]

    # Count optional digits from T[0] to T[M-2]
    c = [0] * 10
    for i in range(M - 1):
        c[T[i] - 48] += 1

    d = T[M - 1] - 48  # mandatory last digit

    ans = bytearray(N)
    mandatory_used = False

    for i in range(N):
        s = S[i] - 48

        if mandatory_used:
            # Find the largest available optional digit
            max_opt = 0
            for v in range(9, 0, -1):
                if c[v] > 0:
                    max_opt = v
                    break
            if max_opt > s:
                ans[i] = max_opt + 48
                c[max_opt] -= 1
            else:
                ans[i] = s + 48
        else:
            if i == N - 1:
                # Last position: must use the mandatory digit
                ans[i] = d + 48
                mandatory_used = True
            else:
                # Find the largest available optional digit
                max_opt = 0
                for v in range(9, 0, -1):
                    if c[v] > 0:
                        max_opt = v
                        break

                best = s
                if max_opt > s:
                    best = max_opt

                if d >= best:
                    ans[i] = d + 48
                    mandatory_used = True
                else:
                    ans[i] = best + 48
                    if best > s:
                        c[best] -= 1

    sys.stdout.buffer.write(ans)
    sys.stdout.buffer.write(b'\n')

if __name__ == "__main__":
    solve()
