        K = K * 10 + (data[idx] - 48)
        idx += 1

    A = [0] * N
    maxv = 0
    for i in range(N):
        while idx < n_data and data[idx] <= 32:
            idx += 1
        v = 0
        while idx < n_data and data[idx] > 32:
            v = v * 10 + (data[idx] - 48)
            idx += 1
        A[i] = v
        if v > maxv:
            maxv = v

